-- DRAFT for Dev A review (spec 10). Generated by data/population/build_clusters.py; do not hand-edit.
-- people = PSA 2020 barangay total x cluster share of the WorldPop 2020 grid (cells -> nearest barangay centroid).
-- Not yet applied to any database. Table shape is a proposal.
create table if not exists clusters (
  cluster_id text primary key,
  barangay_id text not null references barangays (barangay_id),
  label text not null,
  lat double precision not null,
  lng double precision not null,
  people integer not null check (people >= 0),
  people_source text not null default 'psa2020_x_worldpop2020'
);

on conflict (cluster_id) do update set
  label = excluded.label, lat = excluded.lat, lng = excluded.lng,
  people = excluded.people, people_source = excluded.people_source;
